-- rowstile 0.1.0-dev: one_lock_pass_per_type. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowstile makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', '2df9150afad27385', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '2df9150afad27385' THEN
    PERFORM pg_catalog.set_config('authz_migration.read_only', pg_catalog.current_setting('default_transaction_read_only'), false);
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '2df9150afad27385' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only until the migration''s last statement; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = '2df9150afad27385' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM 'd0b91f04206ce683' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      'd0b91f04206ce683', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- trees built beside the ones in use (by the migration before) take their place
CREATE SCHEMA IF NOT EXISTS authz_keep;
ALTER TABLE authz_int."team__parent__tree__next" SET SCHEMA authz_keep;
ALTER TABLE authz_keep."team__parent__tree__next" RENAME TO "team__parent__tree";
ALTER INDEX authz_keep."team__parent__tree__next_pkey" RENAME TO "team__parent__tree_pkey";
ALTER INDEX authz_keep."team__parent__tree__next_ancestor_idx" RENAME TO "team__parent__tree_ancestor_idx";

-- the triggers rebuilt trees made on tables their conditions read
DO $authz_dyn$
DECLARE r record;
BEGIN
  FOR r IN SELECT t.tgname, t.tgrelid::regclass AS tbl FROM pg_catalog.pg_trigger t
           WHERE t.tgname = ANY (ARRAY['authz_team__parent__tree_dep']) LOOP
    EXECUTE format('DROP TRIGGER %I ON %s', r.tgname, r.tbl);
  END LOOP;
END $authz_dyn$;

-- views that change stay where they are, emptied (the same columns, reading nothing) while what they
-- read is dropped and made again; they are defined again below. What the app built on one stays
DO $authz_stub$
DECLARE v text; cols text;
BEGIN
  FOREACH v IN ARRAY ARRAY['authz_int."team__oversee"'] LOOP
    CONTINUE WHEN pg_catalog.to_regclass(v) IS NULL;
    SELECT (SELECT string_agg(format('NULL::%s%s AS %I', pg_catalog.format_type(a.atttypid, a.atttypmod),
        CASE WHEN a.attcollation <> 0 AND a.attcollation <> t.typcollation
             THEN format(' COLLATE %I.%I', cn.nspname, co.collname) ELSE '' END, a.attname), ', ' ORDER BY a.attnum)
      FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_type t ON t.oid = a.atttypid
      LEFT JOIN pg_catalog.pg_collation co ON co.oid = a.attcollation
      LEFT JOIN pg_catalog.pg_namespace cn ON cn.oid = co.collnamespace
      WHERE a.attrelid = pg_catalog.to_regclass(v) AND a.attnum > 0 AND NOT a.attisdropped) INTO cols;
    EXECUTE format('CREATE OR REPLACE VIEW %s AS SELECT %s WHERE false', v, cols);
  END LOOP;
END $authz_stub$;

-- the triggers given to the tables under others: made again below, on what this migration makes
-- @locks ACCESS EXCLUSIVE: the partitions and child tables of the tables rowstile watches
DO $authz_ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT g.tgname, g.tgrelid::regclass AS tbl FROM pg_catalog.pg_trigger g
           JOIN pg_catalog.pg_description d ON d.objoid = g.oid AND d.classoid = 'pg_catalog.pg_trigger'::regclass
           WHERE d.description = 'rowstile: the trigger of the table above, for the rows stored here' LOOP
    EXECUTE pg_catalog.format('DROP TRIGGER %I ON %s', r.tgname, r.tbl);
  END LOOP;
END $authz_ch$;

-- what goes, or is made again
DROP TRIGGER IF EXISTS "authz_team__parent__tree_del" ON "hd"."teams";
DROP TRIGGER IF EXISTS "authz_team__parent__tree_ins" ON "hd"."teams";
DROP TRIGGER IF EXISTS "authz_team__parent__tree_trunc" ON "hd"."teams";
DROP TRIGGER IF EXISTS "authz_team__parent__tree_upd" ON "hd"."teams";
DROP VIEW IF EXISTS
  authz_int."team__parent__tree_links",
  authz_int."team__parent__tree_parents";
DROP FUNCTION IF EXISTS
  authz_int."team__parent__tree__next_compute"(p_ids uuid[]),
  authz_int."team__parent__tree_check_loops"(p_ids uuid[]),
  authz_int."team__parent__tree_compute"(p_ids uuid[]),
  authz_int."team__parent__tree_on_rows"(),
  authz_int."team__parent__tree_on_truncate"(),
  authz_int."team__parent__tree_rebuild"(),
  authz_int."team__parent__tree_refresh"(p_ids uuid[], p_shift boolean, p_loops boolean, p_plain boolean, p_reach uuid[]),
  authz_int."team__parent__tree_shift"(p_ids uuid[], p_below uuid[]),
  authz_int."team__parent__tree_verify"();
DROP INDEX IF EXISTS authz_int."team__parent__tree_ancestor_idx";
DROP TABLE IF EXISTS
  authz_int."team__parent__tree",
  authz_int."team__parent__tree__next";

-- rebuilt inheritance trees start empty
CREATE TEMP TABLE IF NOT EXISTS authz_kept (name text PRIMARY KEY) ON COMMIT DROP;

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'hd_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- Inheritance tables kept whose tables have other tables under them since they were computed (a partition
-- attached or detached: no trigger saw those rows) are computed again
DO $stale$
DECLARE r record;
BEGIN
  IF to_regclass('authz_int.trees') IS NULL THEN RETURN; END IF;
  FOR r IN SELECT n.name, n.oids, n.fn FROM (VALUES ('team__parent__tree', ARRAY[to_regclass('"hd"."teams"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"hd"."teams"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid), 'authz_int."team__parent__tree_rebuild"()')) n(name, oids, fn)
           JOIN authz_int.trees t ON t.name = n.name
           WHERE t.oids IS DISTINCT FROM n.oids AND to_regprocedure(n.fn) IS NOT NULL LOOP
    EXECUTE format('SELECT %s', r.fn);
    UPDATE authz_int.trees SET oids = r.oids WHERE name = r.name;
  END LOOP;
END $stale$;

-- authz_int.trees: its rows again
DELETE FROM authz_int.trees;
INSERT INTO authz_int.trees VALUES
  ('team__parent__tree', 'd2f3dcb328124d24eb0eba163b72ade9', ARRAY[to_regclass('"hd"."teams"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"hd"."teams"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid));

-- team: each row with every ancestor it inherits from, through parent
CREATE TABLE authz_int."team__parent__tree" (descendant uuid NOT NULL, ancestor uuid NOT NULL,
  CONSTRAINT "team__parent__tree_pkey" PRIMARY KEY (descendant, ancestor));
CREATE INDEX "team__parent__tree_ancestor_idx" ON authz_int."team__parent__tree" (ancestor);
INSERT INTO authz_int.locks VALUES ('team', 0) ON CONFLICT DO NOTHING;
-- kept from the last apply if its definition is the same: its rows are current
DO $k$ BEGIN
  IF to_regclass('authz_keep."team__parent__tree"') IS NOT NULL THEN
    DROP TABLE authz_int."team__parent__tree";
    ALTER TABLE authz_keep."team__parent__tree" SET SCHEMA authz_int;
    INSERT INTO pg_temp.authz_kept VALUES ('team__parent__tree') ON CONFLICT DO NOTHING;
  END IF;
END $k$;

-- every parent link, from every source
CREATE VIEW authz_int."team__parent__tree_links" AS
  SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "hd"."teams" r WHERE r."parent_id" IS NOT NULL;

-- walk up from the given rows; a link is followed only if its condition holds on
-- the child, and the parent exists and passes its type's where
CREATE FUNCTION authz_int."team__parent__tree_compute"(p_ids uuid[]) RETURNS TABLE (o_descendant uuid, o_ancestor uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH RECURSIVE up(_d, _a) AS (
    SELECT x."id", x."id" FROM "hd"."teams" x WHERE x."id" = ANY ($1)
    UNION
    SELECT up._d, e._parent
    FROM up
    -- one index lookup per step: joined plainly, a small table gets a full scan at every step
    -- (OFFSET 0 keeps the planner from turning this into a hash join)
    CROSS JOIN LATERAL (SELECT c.* FROM "hd"."teams" c WHERE c."id" = up._a OFFSET 0) c
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "hd"."teams" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up._a OFFSET 0)) e
    WHERE (e._link = 0)
      AND EXISTS (SELECT 1 FROM "hd"."teams" p WHERE p."id" = e._parent))
  SELECT _d, _a FROM up
$f$;

-- what decides inheritance must be IMMUTABLE
DO $imm$
DECLARE d record;
BEGIN

  FOR d IN SELECT DISTINCT p.oid::regprocedure AS fn
           FROM pg_depend dep
           JOIN pg_rewrite w ON w.oid = dep.objid AND dep.classid = 'pg_rewrite'::regclass
           JOIN pg_proc p ON p.oid = dep.refobjid AND dep.refclassid = 'pg_proc'::regclass
           WHERE w.ev_class IN ('authz_int."team__parent__tree_links"'::regclass) AND p.provolatile <> 'i' LOOP
    RAISE EXCEPTION '%: a condition used for inheritance calls %, which is not IMMUTABLE; read tables with a subquery instead, so changes to them are tracked [AZ603]',
      'line 60', d.fn;
  END LOOP;
END $imm$;

-- after a change to the links of p_ids alone (nothing inserted, deleted or renumbered), everything
-- below them (p_below, which includes them) keeps its stored rows among itself, and only rows to the
-- ancestors of p_ids, before or after, can change: to those, each row below now reaches whatever the
-- stored rows of the links leaving the part below lead to. A move of a folder with thousands below it
-- then rewrites (below it) x (its old and new ancestors) rows instead of recomputing every one. That
-- holds only if no link of p_ids, before or after, leads back into the part below them (checked here;
-- false means nothing was done and the caller recomputes). Plans are made for each call's arrays:
-- one made for a few rows would be ruinous for a big move
CREATE FUNCTION authz_int."team__parent__tree_shift"(p_ids uuid[], p_below uuid[]) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET plan_cache_mode = force_custom_plan AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE touched uuid[];
BEGIN
  IF EXISTS (SELECT 1 FROM authz_int."team__parent__tree" t JOIN unnest($2) b(id) ON b.id = t.ancestor
             WHERE t.descendant = ANY ($1) AND t.ancestor <> t.descendant) THEN
    RETURN false;
  END IF;
  IF EXISTS (SELECT 1 FROM unnest($1) b(_y) JOIN "hd"."teams" c ON c."id" = b._y
             CROSS JOIN LATERAL (
               (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "hd"."teams" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
             WHERE (e._link = 0) AND e._parent = ANY ($2)) THEN
    RETURN false;
  END IF;
  -- the ancestors of p_ids before (stored) and after (through their links now): no others change
  touched := ARRAY(
    SELECT t.ancestor FROM authz_int."team__parent__tree" t WHERE t.descendant = ANY ($1) AND t.ancestor <> t.descendant
    UNION
    SELECT u.ancestor FROM unnest($1) b(_y) JOIN "hd"."teams" c ON c."id" = b._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "hd"."teams" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
    JOIN authz_int."team__parent__tree" u ON u.descendant = e._parent
    WHERE (e._link = 0));
  WITH below AS MATERIALIZED (SELECT x AS _y FROM unnest($2) x),
  -- links from the part below to outside it, as they are now
  exits AS MATERIALIZED (
    SELECT e._child AS y, e._parent AS p
    FROM below JOIN "hd"."teams" c ON c."id" = below._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "hd"."teams" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = below._y OFFSET 0)) e
    WHERE (e._link = 0)),
  -- each row below: the touched ancestors it now reaches, through the exits it reaches
  fresh AS MATERIALIZED (
    SELECT DISTINCT d.descendant AS d, u.ancestor AS a
    FROM exits
    JOIN authz_int."team__parent__tree" u ON u.descendant = exits.p AND u.ancestor = ANY (authz__.touched)
    JOIN authz_int."team__parent__tree" d ON d.ancestor = exits.y
    WHERE NOT EXISTS (SELECT 1 FROM below b WHERE b._y = exits.p)),
  stale AS (
    DELETE FROM authz_int."team__parent__tree" t
    WHERE t.ancestor = ANY (authz__.touched) AND t.descendant IN (SELECT _y FROM below)
      AND NOT EXISTS (SELECT 1 FROM fresh o WHERE o.d = t.descendant AND o.a = t.ancestor))
  INSERT INTO authz_int."team__parent__tree" (descendant, ancestor) SELECT d, a FROM fresh ON CONFLICT DO NOTHING;
  RETURN true;
END $f$;

-- recompute the given rows and everything linked below them; p_shift: only their own links changed;
-- p_reach: the rows the statement changed for any tree of the type, when they are more than p_ids; p_held: the
-- type's trigger took the lock rows already
CREATE FUNCTION authz_int."team__parent__tree_refresh"(p_ids uuid[], p_shift boolean DEFAULT false, p_loops boolean DEFAULT false,
                               p_plain boolean DEFAULT false, p_reach uuid[] DEFAULT NULL,
                               p_held boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET plan_cache_mode = force_generic_plan AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE
  affected uuid[]; under text[]; hung text[]; held int[]; stripes boolean; asked bigint; taken bigint; short int;
  locked uuid[]; locked_under text[]; locked_hung text[]; seen uuid[]; most int;
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  IF p_plain THEN
    IF cardinality(p_ids) = 1 AND p_ids[1] IS NOT NULL THEN
      -- (one row, nothing hanging under it: the short way to the same lock rows)
      SELECT h._under, h._hung, coalesce((SELECT l.narrow FROM authz_int.locks l WHERE l.type = 'team'), false),
             coalesce((SELECT s.value::int FROM authz.settings s WHERE s.key = 'tree_lock_limit' AND s.value ~ '^[0-9]{1,9}$'), 1000)
      INTO under, hung, stripes, most
      FROM (SELECT array_agg(e._parent::text ORDER BY e._child::text, e._parent::text) AS _under,
                 array_agg(e._child::text ORDER BY e._child::text, e._parent::text) AS _hung
          FROM unnest($1) AS b(_y) CROSS JOIN LATERAL (
            (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "hd"."teams" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
          WHERE e._parent IS NOT NULL) h;
      affected := p_ids;
      IF authz__.stripes AND authz__.most > 0 THEN
        held := authz_int.tree_lock_one('team', authz__.affected[1]::text, authz__.under, authz__.hung);
      END IF;
      asked := 0;
      taken := 0;
    ELSE
      WITH narrow AS MATERIALIZED (
        SELECT coalesce((SELECT l.narrow FROM authz_int.locks l WHERE l.type = 'team'), false) AS _is,
               coalesce((SELECT s.value::int FROM authz.settings s WHERE s.key = 'tree_lock_limit' AND s.value ~ '^[0-9]{1,9}$'), 1000) AS _most),
      hint AS MATERIALIZED (
        SELECT ARRAY(SELECT x FROM unnest($1) AS x WHERE x IS NOT NULL
                     UNION (SELECT s.descendant FROM authz_int."team__parent__tree" s WHERE s.ancestor = ANY ($1) LIMIT (SELECT n._most + 1 FROM narrow n))
                     UNION SELECT x FROM unnest(authz__.seen) AS x) AS _ids),
      hangs AS MATERIALIZED (
        SELECT h._under, h._hung
        FROM (SELECT array_agg(e._parent::text ORDER BY e._child::text, e._parent::text) AS _under,
                   array_agg(e._child::text ORDER BY e._child::text, e._parent::text) AS _hung
            FROM unnest($1) AS b(_y) CROSS JOIN LATERAL (
              (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "hd"."teams" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
            WHERE e._parent IS NOT NULL) h),
      need AS MATERIALIZED (
        SELECT y._slot, bool_or(y._upd) AS _upd
        FROM (SELECT -1 AS _slot, false AS _upd WHERE pg_catalog.current_setting('transaction_isolation') <> 'read committed'
              UNION ALL
              SELECT (pg_catalog.hashtext(w._id) & 1023) * 5, true FROM (SELECT x::text FROM hint i, unnest(i._ids) x) w(_id) WHERE w._id IS NOT NULL
              UNION ALL
              SELECT (pg_catalog.hashtext(w._id) & 1023) * 5 + g._sub, false FROM (SELECT x::text FROM hint i, unnest(i._ids) x) w(_id), generate_series(1, 4) g(_sub)
              WHERE pg_catalog.current_setting('transaction_isolation') <> 'read committed' AND w._id IS NOT NULL
              UNION ALL
              SELECT (pg_catalog.hashtext(u._above) & 1023) * 5, false FROM (SELECT z.a, z.b FROM hangs p, unnest(p._under, p._hung) z(a, b)) u(_above, _hung) WHERE u._above IS NOT NULL
              UNION ALL
              SELECT (pg_catalog.hashtext(u._above) & 1023) * 5 + 1 + ((pg_catalog.hashtext(u._hung) >> 12) & 3), true
              FROM (SELECT z.a, z.b FROM hangs p, unnest(p._under, p._hung) z(a, b)) u(_above, _hung) WHERE u._above IS NOT NULL) y
        WHERE (SELECT n._is FROM narrow n) AND (SELECT cardinality(i._ids) FROM hint i) <= (SELECT n._most FROM narrow n)
        GROUP BY y._slot),
      got AS MATERIALIZED (
        SELECT o._slot, o._upd,
               CASE WHEN o._slot = -1 THEN (SELECT 1 FROM authz_int.locks l WHERE l.type = 'team' FOR SHARE)
                    WHEN o._upd THEN (SELECT 1 FROM authz_int.tree_locks_1024_4 t
                                      WHERE t.type = 'team' AND t.slot = o._slot FOR UPDATE)
                    ELSE (SELECT 1 FROM authz_int.tree_locks_1024_4 t
                          WHERE t.type = 'team' AND t.slot = o._slot FOR SHARE) END AS _held
        FROM (SELECT n._slot, n._upd FROM need n ORDER BY n._slot OFFSET 0) o),
      bumped AS (
        UPDATE authz_int.tree_locks_1024_4 t SET n = t.n + 1 FROM got g
        WHERE g._upd AND g._held = 1 AND t.type = 'team' AND t.slot = g._slot RETURNING 1)
      SELECT i._ids, p._under, p._hung, (SELECT n._is FROM narrow n), (SELECT n._most FROM narrow n),
             (SELECT count(*) FROM need), (SELECT count(*) FROM got g WHERE g._held = 1),
             ARRAY(SELECT g._slot * 2 + g._upd::int FROM got g WHERE g._held = 1)
      INTO affected, under, hung, stripes, most, asked, taken, held
      FROM hint i, hangs p;
    END IF;
    IF NOT authz__.stripes OR cardinality(authz__.affected) > authz__.most THEN
      -- (a type whose every tree write takes its row; a write of more objects than the setting says)
      PERFORM authz_int.tree_lock_all('team');
      held := ARRAY[-1];
    ELSIF authz__.taken <> authz__.asked THEN
      PERFORM authz_int.tree_locks_gone();
    END IF;
    LOOP
      locked := affected;
      locked_under := under;
      locked_hung := hung;
      WITH RECURSIVE down(id) AS (
      SELECT x FROM unnest($1) AS x WHERE x IS NOT NULL
      UNION
      SELECT e._child FROM down CROSS JOIN LATERAL (
        (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "hd"."teams" r WHERE r."parent_id" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)) e)
      SELECT (SELECT array_agg(d.id) FROM down d), h._under, h._hung INTO affected, under, hung
      FROM (SELECT array_agg(e._parent::text ORDER BY e._child::text, e._parent::text) AS _under,
                   array_agg(e._child::text ORDER BY e._child::text, e._parent::text) AS _hung
            FROM unnest($1) AS b(_y) CROSS JOIN LATERAL (
              (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "hd"."teams" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
            WHERE e._parent IS NOT NULL) h;
      -- the walk, under the locks, found nothing that wasn't locked: nearly always
      EXIT WHEN authz__.held = ARRAY[-1]
                OR (authz__.affected <@ authz__.locked AND authz__.under IS NOT DISTINCT FROM authz__.locked_under
                    AND authz__.hung IS NOT DISTINCT FROM authz__.locked_hung);
      SELECT l.o_held, l.o_short INTO held, short
      FROM authz_int.tree_lock('team', authz__.affected::text[], authz__.under, authz__.hung, authz__.held, false) l;
      IF authz__.short > 0 THEN
        SELECT l.o_held INTO held
        FROM authz_int.tree_lock('team', authz__.affected::text[], authz__.under, authz__.hung, authz__.held, true) l;
      END IF;
    END LOOP;
  ELSE
    LOOP
      BEGIN
    WITH narrow AS MATERIALIZED (
          SELECT coalesce((SELECT l.narrow FROM authz_int.locks l WHERE l.type = 'team'), false) AS _is,
                 coalesce((SELECT s.value::int FROM authz.settings s WHERE s.key = 'tree_lock_limit' AND s.value ~ '^[0-9]{1,9}$'), 1000) AS _most),
        hint AS MATERIALIZED (
          SELECT ARRAY(SELECT x FROM unnest($1) AS x WHERE x IS NOT NULL
                       UNION (SELECT s.descendant FROM authz_int."team__parent__tree" s WHERE s.ancestor = ANY ($1) LIMIT (SELECT n._most + 1 FROM narrow n))
                       UNION SELECT x FROM unnest(authz__.seen) AS x) AS _ids),
        hangs AS MATERIALIZED (
          SELECT h._under, h._hung
          FROM (SELECT array_agg(e._parent::text ORDER BY e._child::text, e._parent::text) AS _under,
                     array_agg(e._child::text ORDER BY e._child::text, e._parent::text) AS _hung
              FROM unnest($1) AS b(_y) CROSS JOIN LATERAL (
                (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "hd"."teams" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
              WHERE e._parent IS NOT NULL) h),
        need AS MATERIALIZED (
          SELECT y._slot, bool_or(y._upd) AS _upd
          FROM (SELECT -1 AS _slot, false AS _upd WHERE pg_catalog.current_setting('transaction_isolation') <> 'read committed'
                UNION ALL
                SELECT (pg_catalog.hashtext(w._id) & 1023) * 5, true FROM (SELECT x::text FROM hint i, unnest(i._ids) x) w(_id) WHERE w._id IS NOT NULL
                UNION ALL
                SELECT (pg_catalog.hashtext(w._id) & 1023) * 5 + g._sub, false FROM (SELECT x::text FROM hint i, unnest(i._ids) x) w(_id), generate_series(1, 4) g(_sub)
                WHERE pg_catalog.current_setting('transaction_isolation') <> 'read committed' AND w._id IS NOT NULL
                UNION ALL
                SELECT (pg_catalog.hashtext(u._above) & 1023) * 5, false FROM (SELECT z.a, z.b FROM hangs p, unnest(p._under, p._hung) z(a, b)) u(_above, _hung) WHERE u._above IS NOT NULL
                UNION ALL
                SELECT (pg_catalog.hashtext(u._above) & 1023) * 5 + 1 + ((pg_catalog.hashtext(u._hung) >> 12) & 3), true
                FROM (SELECT z.a, z.b FROM hangs p, unnest(p._under, p._hung) z(a, b)) u(_above, _hung) WHERE u._above IS NOT NULL) y
          WHERE (SELECT n._is FROM narrow n) AND (SELECT cardinality(i._ids) FROM hint i) <= (SELECT n._most FROM narrow n)
          GROUP BY y._slot),
        got AS MATERIALIZED (
          SELECT o._slot, o._upd,
                 CASE WHEN o._slot = -1 THEN (SELECT 1 FROM authz_int.locks l WHERE l.type = 'team' FOR SHARE)
                      WHEN o._upd THEN (SELECT 1 FROM authz_int.tree_locks_1024_4 t
                                        WHERE t.type = 'team' AND t.slot = o._slot FOR UPDATE)
                      ELSE (SELECT 1 FROM authz_int.tree_locks_1024_4 t
                            WHERE t.type = 'team' AND t.slot = o._slot FOR SHARE) END AS _held
          FROM (SELECT n._slot, n._upd FROM need n ORDER BY n._slot OFFSET 0) o),
        bumped AS (
          UPDATE authz_int.tree_locks_1024_4 t SET n = t.n + 1 FROM got g
          WHERE g._upd AND g._held = 1 AND t.type = 'team' AND t.slot = g._slot RETURNING 1)
        SELECT i._ids, p._under, p._hung, (SELECT n._is FROM narrow n), (SELECT n._most FROM narrow n),
               (SELECT count(*) FROM need), (SELECT count(*) FROM got g WHERE g._held = 1),
               ARRAY(SELECT g._slot * 2 + g._upd::int FROM got g WHERE g._held = 1)
        INTO affected, under, hung, stripes, most, asked, taken, held
        FROM hint i, hangs p;
        IF NOT authz__.stripes OR cardinality(authz__.affected) > authz__.most THEN
          -- (a type whose every tree write takes its row; a write of more objects than the setting says)
          PERFORM authz_int.tree_lock_all('team');
          held := ARRAY[-1];
        ELSIF authz__.taken <> authz__.asked THEN
          PERFORM authz_int.tree_locks_gone();
        END IF;
        LOOP
          locked := affected;
          locked_under := under;
          locked_hung := hung;
          WITH RECURSIVE down(id) AS (
          SELECT x FROM unnest($1) AS x WHERE x IS NOT NULL
          UNION
          SELECT e._child FROM down CROSS JOIN LATERAL (
            (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "hd"."teams" r WHERE r."parent_id" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)) e)
          SELECT (SELECT array_agg(d.id) FROM down d), h._under, h._hung INTO affected, under, hung
          FROM (SELECT array_agg(e._parent::text ORDER BY e._child::text, e._parent::text) AS _under,
                       array_agg(e._child::text ORDER BY e._child::text, e._parent::text) AS _hung
                FROM unnest($1) AS b(_y) CROSS JOIN LATERAL (
                  (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "hd"."teams" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
                WHERE e._parent IS NOT NULL) h;
          -- the walk, under the locks, found nothing that wasn't locked: nearly always
          EXIT WHEN authz__.held = ARRAY[-1]
                    OR (authz__.affected <@ authz__.locked AND authz__.under IS NOT DISTINCT FROM authz__.locked_under
                        AND authz__.hung IS NOT DISTINCT FROM authz__.locked_hung);
          SELECT l.o_held, l.o_short INTO held, short
          FROM authz_int.tree_lock('team', authz__.affected::text[], authz__.under, authz__.hung, authz__.held, false) l;
          IF authz__.short > 0 THEN
            seen := affected;
            RAISE EXCEPTION USING ERRCODE = 'AZL01';
          END IF;
        END LOOP;
        EXIT;
      EXCEPTION WHEN SQLSTATE 'AZL01' THEN
        -- what this try took is let go. Again, in order: what is stored now and what the walk had found (seen keeps
        -- its value: a block that is rolled back doesn't take its variables back). Without it a row that hangs
        -- below without inheriting, which the stored rows never show, would be asked for without waiting each time
        NULL;
      END;
    END LOOP;
  END IF;
  IF cardinality(affected) > 1000 THEN
    -- (a write this big gets plans of its own; the setting is as it was when this function ends)
    PERFORM pg_catalog.set_config('plan_cache_mode', 'force_custom_plan', true);
  END IF;
  IF p_loops THEN PERFORM authz_int."team__parent__tree_check_loops"($1); END IF;
  IF NOT (p_shift AND authz_int."team__parent__tree_shift"(p_ids, affected)) THEN
    DELETE FROM authz_int."team__parent__tree" WHERE descendant = ANY (affected);
    INSERT INTO authz_int."team__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."team__parent__tree_compute"(affected);
  END IF;
  PERFORM authz_int.changed('team', affected::text[], 'inheritance');
END $f$;

-- recompute everything (backfill, TRUNCATE), 10000 rows at a time
CREATE FUNCTION authz_int."team__parent__tree_rebuild"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE batch uuid[];
BEGIN
  PERFORM authz_int.tree_lock_all('team');
  DELETE FROM authz_int."team__parent__tree";
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "hd"."teams") k GROUP BY (k.n - 1) / 10000 LOOP
    INSERT INTO authz_int."team__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."team__parent__tree_compute"(batch);
  END LOOP;
END $f$;
CREATE FUNCTION authz_int."team__parent__tree_on_truncate"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN PERFORM authz_int."team__parent__tree_rebuild"(); RETURN NULL; END $f$;

-- what a rebuild would give against what is stored, 10000 rows at a time; then nothing stored for a row
-- that is gone
CREATE FUNCTION authz_int."team__parent__tree_verify"() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE batch uuid[];
BEGIN
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "hd"."teams") k GROUP BY (k.n - 1) / 10000 LOOP
    IF EXISTS (WITH fresh AS MATERIALIZED (SELECT o_descendant AS d, o_ancestor AS a FROM authz_int."team__parent__tree_compute"(batch)),
                    stored AS MATERIALIZED (SELECT descendant AS d, ancestor AS a FROM authz_int."team__parent__tree"
                                            WHERE descendant = ANY (batch))
               (SELECT d, a FROM fresh EXCEPT SELECT d, a FROM stored)
               UNION ALL
               (SELECT d, a FROM stored EXCEPT SELECT d, a FROM fresh)) THEN
      RETURN false;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM authz_int."team__parent__tree" s
             WHERE NOT EXISTS (SELECT 1 FROM "hd"."teams" x WHERE x."id" = s.descendant)) THEN
    RETURN false;
  END IF;
  RETURN true;
END $f$;

-- the tree's own columns may not loop (links through tables may: they add nothing)
CREATE VIEW authz_int."team__parent__tree_parents" AS
  SELECT r."id" AS _child, r."parent_id" AS _parent FROM "hd"."teams" r WHERE r."parent_id" IS NOT NULL;
CREATE FUNCTION authz_int."team__parent__tree_check_loops"(p_ids uuid[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE bad text;
BEGIN
  WITH RECURSIVE up(start, id) AS (
    SELECT e._child, e._parent FROM authz_int."team__parent__tree_parents" e WHERE e._child = ANY ($1)
    UNION
    SELECT up.start, e._parent FROM up CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT r."id" AS _child, r."parent_id" AS _parent FROM "hd"."teams" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up.id OFFSET 0)) e)
  SELECT start::text INTO bad FROM up WHERE id = start LIMIT 1;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'team % cannot be moved inside itself', bad USING ERRCODE = 'check_violation', HINT = 'rowstile help AZ713';
  END IF;
END $f$;

-- rows inserted, deleted, moved, or whose id or conditions change
CREATE FUNCTION authz_int."team__parent__tree_on_rows"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET plan_cache_mode = force_generic_plan AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE ids uuid[]; shift boolean := false; plain boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT n."id" FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    -- rows whose id changed: the old id disappears and the new one appears
    ids := ARRAY(
      SELECT o."id" FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id" = o."id")
      UNION SELECT n."id" FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id" = n."id"));
    shift := cardinality(ids) = 0;
    ids := ARRAY(
      SELECT n."id" FROM new_rows n JOIN old_rows o ON o."id" = n."id"
      WHERE n."parent_id" IS DISTINCT FROM o."parent_id"
      UNION SELECT unnest(authz__.ids));
  ELSE
    ids := ARRAY(SELECT o."id" FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    -- (nothing hangs under a row just made; under another, its links say: the stored rows don't hold
    -- what hangs under a row without inheriting from it)
    IF TG_OP = 'INSERT' THEN
      plain := true;
    ELSE
      plain := NOT EXISTS (SELECT 1 FROM unnest(authz__.ids) AS b(_y) CROSS JOIN LATERAL (
        (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "hd"."teams" r WHERE r."parent_id" IS NOT NULL) x WHERE x._parent = b._y OFFSET 0)) e);
    END IF;
    PERFORM authz_int."team__parent__tree_refresh"(ids, shift, TG_OP <> 'DELETE', plain);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_team__parent__tree_ins" AFTER INSERT ON "hd"."teams"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."team__parent__tree_on_rows"();
CREATE TRIGGER "authz_team__parent__tree_upd" AFTER UPDATE ON "hd"."teams"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."team__parent__tree_on_rows"();
CREATE TRIGGER "authz_team__parent__tree_del" AFTER DELETE ON "hd"."teams"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."team__parent__tree_on_rows"();
CREATE TRIGGER "authz_team__parent__tree_trunc" AFTER TRUNCATE ON "hd"."teams"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."team__parent__tree_on_truncate"();
COMMENT ON TRIGGER "authz_team__parent__tree_trunc" ON "hd"."teams" IS 'rowstile: for a TRUNCATE of the tables under its table too';

-- backfill from the rows already there (unless the tree was kept)
DO $b$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'team__parent__tree') THEN
    PERFORM authz_int."team__parent__tree_rebuild"();
  END IF;
END $b$;

-- team__parent__tree was built beside the one in use, from a snapshot: what changed since is done again
DO $authz_catch_up$
DECLARE v authz_int.next_trees;
BEGIN
  SELECT * INTO v FROM authz_int.next_trees WHERE name = 'team__parent__tree';
  IF v.name IS NULL OR NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'team__parent__tree') THEN
    RAISE EXCEPTION 'rowstile: team__parent__tree was not built beside the one in use (the migration before this one does that) [AZ608]';
  END IF;
  IF coalesce((SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_to'), 0) > v.feed
     OR (SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_txid')
        >= pg_catalog.pg_snapshot_xmin(v.snap)::text::bigint
     OR EXISTS (SELECT 1 FROM authz.changes c WHERE c.object_type = 'team' AND '*' = ANY (c.object_ids)
                AND c.cause <> 'dependent'
                AND NOT pg_catalog.pg_visible_in_snapshot(c.txid::text::xid8, v.snap)) THEN
    PERFORM authz_int."team__parent__tree_rebuild"();          -- the feed doesn't say everything that changed since: all of it
  ELSE
    PERFORM authz_int."team__parent__tree_refresh"(ARRAY(SELECT x."id" FROM "hd"."teams" x WHERE NOT pg_catalog.pg_visible_in_snapshot(((((pg_catalog.pg_current_xact_id()::text::bigint >> 32) - CASE WHEN x.xmin::text::bigint > (pg_catalog.pg_current_xact_id()::text::bigint & 4294967295) THEN 1 ELSE 0 END) << 32) | x.xmin::text::bigint)::text::xid8, v.snap)
      UNION SELECT y::uuid FROM authz.changes c, unnest(c.object_ids) y
      WHERE c.object_type = 'team' AND c.cause <> 'dependent'
        AND c.txid >= pg_catalog.pg_snapshot_xmin(v.snap)::text::bigint
        AND NOT pg_catalog.pg_visible_in_snapshot(c.txid::text::xid8, v.snap) AND y <> '*'));
    -- rows deleted since
    DELETE FROM authz_int."team__parent__tree" d WHERE NOT EXISTS (SELECT 1 FROM "hd"."teams" x WHERE x."id" = d.descendant)
                             OR NOT EXISTS (SELECT 1 FROM "hd"."teams" x WHERE x."id" = d.ancestor);
  END IF;
  DELETE FROM authz_int.next_trees WHERE name = 'team__parent__tree';
END $authz_catch_up$;

-- team.oversee (line 66): lead or parent.oversee
CREATE OR REPLACE VIEW authz_int."team__oversee" AS
  SELECT c.descendant AS id FROM authz_int."team__parent__tree" c
  WHERE c.ancestor IN (SELECT s.id FROM authz_int."team__oversee__start"() s(id));

-- What the app role evaluates itself (its rules, the views they read, the rules' own functions, the masked views)
-- calls nothing of the app's that may read data: a call the condition's text doesn't show isn't run as the owner
DO $ac$
DECLARE r record;
BEGIN
  FOR r IN
    WITH RECURSIVE read(classid, objid, what) AS (
      SELECT x.classid, x.objid, x.what FROM (
        SELECT 'pg_policy'::regclass::oid AS classid, p.oid AS objid,
               format('the %s rule of %s', substr(p.polname::text, 7), p.polrelid::regclass) AS what
        FROM pg_policy p JOIN pg_description d ON d.objoid = p.oid AND d.classoid = 'pg_policy'::regclass
         AND d.description IN ('rowstile')
        UNION ALL
        SELECT 'pg_proc'::regclass::oid, f.oid, 'the rules of ' || split_part(f.proname::text, ':', 1)
        FROM pg_proc f WHERE f.pronamespace = 'authz_gen'::regnamespace
        UNION ALL
        SELECT 'pg_rewrite'::regclass::oid, w.oid, 'the masked view ' || c.oid::regclass
        FROM pg_class c JOIN pg_description d ON d.objoid = c.oid AND d.classoid = 'pg_class'::regclass
         AND d.description IN ('rowstile masked view')
        JOIN pg_rewrite w ON w.ev_class = c.oid) x
      UNION
      -- (the views they read, and those these read: a view runs what it calls as whoever reads it)
      SELECT 'pg_rewrite'::regclass::oid, w.oid, rd.what
      FROM read rd JOIN pg_depend dep ON dep.classid = rd.classid AND dep.objid = rd.objid
       AND dep.refclassid = 'pg_class'::regclass
      JOIN pg_class v ON v.oid = dep.refobjid AND v.relkind = 'v' AND v.relnamespace = 'authz_int'::regnamespace
      JOIN pg_rewrite w ON w.ev_class = v.oid)
    SELECT rd.what, fn.oid::regprocedure::text AS fn
    FROM read rd JOIN pg_depend dep ON dep.classid = rd.classid AND dep.objid = rd.objid
    JOIN pg_proc fn ON fn.oid = CASE dep.refclassid
        WHEN 'pg_proc'::regclass THEN dep.refobjid
        WHEN 'pg_operator'::regclass THEN (SELECT o.oprcode FROM pg_operator o WHERE o.oid = dep.refobjid) END
    WHERE fn.pronamespace NOT IN (SELECT n.oid FROM pg_namespace n
                                  WHERE n.nspname IN ('pg_catalog', 'authz', 'authz_gen', 'authz_int'))
      AND fn.provolatile <> 'i'
      AND fn.prolang NOT IN (SELECT l.oid FROM pg_language l WHERE l.lanname IN ('internal', 'c'))
    ORDER BY 1, 2 LIMIT 1
  LOOP
    RAISE EXCEPTION '%: a condition calls %, and nothing in its text shows the call (a function of the row read as a column, a cast, an operator written OPERATOR(...)), so the app role would run it with its own rights, not the policy''s [AZ628]', r.what, r.fn
      USING HINT = 'call it by its name, with parentheses, on the row''s columns, as {app.blocked_doc(this.id)}: rowstile then runs it with the policy''s rights. A function that reads nothing may be marked IMMUTABLE instead';
  END LOOP;
END $ac$;

-- The partitions of each table with rules and the tables that inherit from one: row-level security on, with
-- no policies of their own, so they are read and written through it only (read directly, they would skip its rules
-- and triggers). Every apply and every migration: one made or attached since is closed too (it alone is locked,
-- as CHILD_TRIGGERS locks only one that lacks the triggers)
DO $rls$
DECLARE c regclass;
BEGIN
  FOR c IN WITH RECURSIVE d(oid) AS (
             SELECT i.inhrelid FROM pg_catalog.pg_inherits i
             WHERE i.inhparent = ANY (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"hd"."comments"', '"hd"."customer_orgs"', '"hd"."integrations"', '"hd"."support_access"', '"hd"."team_leads"', '"hd"."team_members"', '"hd"."teams"', '"hd"."tickets"', '"hd"."users"', '"hd"."workspaces"']::text[]) x)
             UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass FROM d JOIN pg_catalog.pg_class k ON k.oid = d.oid WHERE NOT k.relrowsecurity LOOP
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', c);
  END LOOP;
END $rls$;

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

SELECT authz_int.sync_refresh('f9f5062dcba084dd7bcc92d9c3232d1c');
DO $sw$
DECLARE n bigint; m bigint;
BEGIN
  SELECT count(*) FILTER (WHERE g.caveat IS NOT NULL), count(*) FILTER (WHERE g.subject_type = 'link') INTO n, m
  FROM authz.shares g WHERE (g.object_type = 'ticket' AND g.relation = 'responder') OR (g.object_type = 'ticket' AND g.relation = 'cc') OR (g.object_type = 'ticket' AND g.relation LIKE 'role:%');
  IF n > 0 THEN
    RAISE WARNING '% shares with a caveat give nothing through the sync index: a caveat is checked at each request, with what it says', n;
  END IF;
  IF m > 0 THEN
    RAISE WARNING '% share links give nothing through the sync index: a synced client is a principal, without links', m;
  END IF;
END $sw$;

REVOKE SELECT ON ALL TABLES IN SCHEMA authz_gen, authz_int FROM "hd_app";
GRANT SELECT ON authz_gen.policy_lines, authz_int."customer_org__member", authz_int."team__lead", authz_int."team__manage", authz_int."team__member", authz_int."team__oversee", authz_int."team__view", authz_int."ticket__cc", authz_int."ticket__reply", authz_int."ticket__responder", authz_int."ticket__roles:work", authz_int."ticket__view", authz_int."ticket__work", authz_int."user__org_tickets", authz_int."user__self", authz_int."workspace__admin", authz_int."workspace__agent", authz_int."workspace__connected", authz_int."workspace__manage", authz_int."workspace__member", authz_int."workspace__view", authz_int."workspace__work", authz_int."workspace__work_all" TO "hd_app";

-- The sync role reads the index, and nothing else rowstile keeps
DO $sr$
DECLARE v_sync oid := to_regrole('"hd_electric"'); v_app oid := to_regrole('"hd_app"'); v_cols text;
BEGIN
  IF v_sync IS NULL THEN
    RAISE EXCEPTION 'the sync role hd_electric does not exist [AZ808]'
      USING HINT = 'make it for the engine: CREATE ROLE hd_electric LOGIN REPLICATION BYPASSRLS, then apply again';
  END IF;
  IF (SELECT r.rolsuper FROM pg_catalog.pg_roles r WHERE r.oid = v_sync) THEN
    RAISE EXCEPTION 'the sync role hd_electric is a superuser, which may turn row-level security off and change the rules [AZ808]'
      USING HINT = 'the engine connects as a role of its own: CREATE ROLE sync_engine LOGIN REPLICATION BYPASSRLS';
  END IF;
  IF pg_catalog.pg_has_role(v_sync, CURRENT_USER, 'MEMBER') THEN
    RAISE EXCEPTION 'the sync role hd_electric is the role that applies the policy (%), or a member of it [AZ808]', CURRENT_USER
      USING HINT = 'the engine connects as a role of its own, which owns nothing of the database';
  END IF;
  IF v_app IS NOT NULL AND (pg_catalog.pg_has_role(v_sync, v_app, 'MEMBER') OR pg_catalog.pg_has_role(v_app, v_sync, 'MEMBER')) THEN
    RAISE EXCEPTION 'the sync role hd_electric and the app role hd_app are one another''s members: the app would read every row [AZ808]'
      USING HINT = 'the engine connects as a role of its own, which the app role is not a member of, nor it of the app role';
  END IF;
  SELECT pg_catalog.string_agg(m.tbl || '.' || m.col, ', ' ORDER BY m.tbl, m.col) INTO v_cols FROM authz_int.masked_columns m
  WHERE pg_catalog.has_column_privilege(v_sync, m.tbl, m.col, 'SELECT');
  IF v_cols IS NOT NULL THEN
    RAISE EXCEPTION 'the sync role hd_electric may read masked columns: % [AZ809]', v_cols
      USING HINT = 'it reads every row, so a masked column would reach every client: revoke SELECT on the table, grant the other columns (GRANT SELECT (id, name) ON ...), then apply again';
  END IF;
END $sr$;
GRANT USAGE ON SCHEMA authz_sync TO "hd_electric";
GRANT SELECT ON ALL TABLES IN SCHEMA authz_sync TO "hd_electric";

